import re

PUSH_RE = re.compile(r"^\s*git\s+push(\s|$)")
TEST_RE = re.compile(r"pytest|unittest|npm\s+test|yarn\s+test|pnpm\s+test|go\s+test|cargo\s+test|mvn\s+test|gradle\s+test|make\s+test|tox|nox|jest|vitest|mocha|rspec|phpunit|ctest", re.IGNORECASE)


def _is_git_push(action):
    if action.get("tool_name") != "Bash":
        return False
    args = action.get("arguments") or {}
    cmd = args.get("command")
    if not isinstance(cmd, str):
        return None
    return bool(PUSH_RE.search(cmd))


def check(action, state, log, context):
    is_push = _is_git_push(action)
    if is_push is None:
        return ask("Bash command argument missing or unparsable; cannot verify pre-push test run.")
    if not is_push:
        return allow("Not a git push command; rule does not apply.")

    # Look for a recent successful test run in this session/task.
    results = log.search({
        "from": "actions",
        "limit": 50,
        "order_by": [{"field": "seq", "direction": "desc"}],
        "select": ["seq", "tool_name", "arguments", "outcome", "result_text"],
        "where": {
            "tool_name": {"eq": "Bash"},
            "outcome": {"eq": "success"},
            "arguments.command": {"regex": "pytest|unittest|npm\\s+test|yarn\\s+test|pnpm\\s+test|go\\s+test|cargo\\s+test|mvn\\s+test|gradle\\s+test|make\\s+test|tox|nox|jest|vitest|mocha|rspec|phpunit|ctest"}
        }
    }) or []

    last_push_seq = -1
    push_results = log.search({
        "from": "actions",
        "limit": 50,
        "order_by": [{"field": "seq", "direction": "desc"}],
        "select": ["seq", "tool_name", "arguments"],
        "where": {
            "tool_name": {"eq": "Bash"},
            "arguments.command": {"regex": "^\\s*git\\s+push(\\s|$)"}
        }
    }) or []
    for p in push_results:
        seq = p.get("seq")
        if isinstance(seq, int) and seq > last_push_seq:
            last_push_seq = seq

    refs = []
    for r in results:
        seq = r.get("seq")
        if not isinstance(seq, int):
            continue
        if seq > last_push_seq:
            refs.append({"seq": seq, "tool_name": r.get("tool_name")})

    if refs:
        return allow("Found a successful test run after the last git push and before this push.", evidence_refs=refs)

    return reject("git push attempted without a successful test run since the last push. Run tests (e.g., pytest) before pushing.")

