        return int(round(float(value) * 100))
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        m = re.search(r"-?\d+(?:\.\d+)?", s.replace(",", ""))
        if not m:
            return None
        try:
            return int(round(float(m.group(0)) * 100))
        except Exception:
            return None
    return None


